// Module cancellation, key: the order id. Owns R6.1 (cancel an order before any step committed), R6.2 (a customer
// cancel during processing: stop, compensate, cancel), R6.3 (a refused cancel: cancel-refused; an ended order changes
// nothing), R6.4 (a cancel before clearing counts), S4 and S7 (which carrier reports prove collection before the cancel),
// S6 (one collection ends the right to cancel the whole order). Calls fraud, order-progress, fulfilment, statuses and
// notices. Always returns `output`.

const COLLECTED = ['collected', 'inTransit', 'delivered'];
const DONE = ['completed', 'failed', 'cancelled'];

export function step(input, ctx) {
  switch (input.op) {
    case 'customer-cancel': return customerCancel(input, ctx);
    case 'cancel-order': return { output: { verdict: cancelOrder(input.at, input.reason, ctx) } };
  }
  throw new Error(`cancellation: unknown op ${input.op}`);
}

function customerCancel(input, ctx) {
  if (input.phase === 'ended') return { output: { verdict: 'nothing' } };        // R6.3, S15
  if (input.phase === 'not-cleared') {                                           // R6.4: counts
    ctx.call('fraud', ctx.key, { op: 'stop' });
    cancelOrder(input.at, 'customer', ctx);
    return { output: { verdict: 'counts' } };
  }
  // processing (R6.2, R6.3): judge on the reports that reached us before this cancel (S4, S7).
  const fs = ctx.call('statuses', ctx.key, { op: 'get' }).fulfilments;
  const cancelAt = Date.parse(input.at);
  let collected = false;
  for (const f of fs) {
    if (f.status === 'unavailable' || f.status === 'cancelled') continue;
    const r = ctx.call('fulfilment', f.fulfilmentId, { op: 'get' });
    for (const rep of r.reports ?? []) {
      if (COLLECTED.includes(rep.meaning) && Date.parse(rep.reportedAt) <= cancelAt) collected = true;
    }
  }
  if (collected) {
    ctx.call('notices', ctx.key, { op: 'send', template: 'cancel-refused', about: ctx.key, occurrence: input.eventId });
    return { output: { verdict: 'refused' } };
  }
  // Counted: stop the order, stop every open fulfilment (compensation runs there), cancel what is left.
  ctx.call('order-progress', ctx.key, { op: 'stop' });
  for (const f of fs) {
    if (DONE.includes(f.status) || f.status === 'unavailable') continue;
    ctx.call('fulfilment', f.fulfilmentId, { op: 'stop', at: input.at });
    ctx.call('statuses', ctx.key, { op: 'set', fulfilmentId: f.fulfilmentId, status: 'cancelled' });
  }
  ctx.call('statuses', ctx.key, { op: 'set', fulfilmentId: null, status: 'cancelled' });
  ctx.call('notices', ctx.key, { op: 'send', template: 'order-cancelled', about: ctx.key });
  return { output: { verdict: 'counts' } };
}

// R6.1: every fulfilment not completed, failed or cancelled becomes cancelled, then the order, then the notice.
// Used before any step committed (R2.1, R2.2, R3.2, R6.4). Returns 'done'.
function cancelOrder(at, reason, ctx) {
  const fs = ctx.call('statuses', ctx.key, { op: 'get' }).fulfilments;
  for (const f of fs) {
    if (DONE.includes(f.status)) continue;
    ctx.call('statuses', ctx.key, { op: 'set', fulfilmentId: f.fulfilmentId, status: 'cancelled' });
  }
  ctx.call('statuses', ctx.key, { op: 'set', fulfilmentId: null, status: 'cancelled' });
  ctx.call('notices', ctx.key, { op: 'send', template: 'order-cancelled', about: ctx.key });
  return 'done';
}
// Module order-progress, key: the order id. Owns R4.1 (processing once the order is ready) and R4.5 (the order
// outcome once every fulfilment has ended). Calls statuses only. Always returns `output`.

export function step(input, ctx) {
  switch (input.op) {
    case 'ready': return ready(input, ctx);
    case 'ended': return ended(input, ctx);
    case 'stop': return stop(input, ctx);
    case 'resume': return resume(input, ctx);
  }
  throw new Error(`order-progress: unknown op ${input.op}`);
}

function out(st) {
  return { output: { state: st.status, outcome: st.outcome ?? null, at: st.at ?? null } };
}

function ready(input, ctx) {
  // Once (R4.1): the order and every available fulfilment become processing, within 60 min of the ready time.
  if (ctx.state && ctx.state.status !== 'idle') return out(ctx.state);
  for (const f of input.fulfilments) {
    if (f.available) ctx.call('statuses', ctx.key, { op: 'set', fulfilmentId: f.fulfilmentId, status: 'processing' });
  }
  ctx.call('statuses', ctx.key, { op: 'set', fulfilmentId: null, status: 'processing' });
  const st = { status: 'processing', outcome: null, at: input.at };
  return { ...out(st), state: st };
}

function ended(input, ctx) {
  const cur = ctx.state;
  if (!cur || cur.status !== 'processing') return out(cur ?? { status: 'idle' });
  const fs = ctx.call('statuses', ctx.key, { op: 'get' }).fulfilments;
  const open = fs.some(f => !['completed', 'failed', 'cancelled'].includes(f.status) && f.status !== 'unavailable');
  if (open) return out(cur);
  const has = s => fs.some(f => f.status === s);
  const outcome = has('completed') ? 'completed' : has('failed') ? 'failed' : 'cancelled';
  ctx.call('statuses', ctx.key, { op: 'set', fulfilmentId: null, status: outcome });
  const st = { status: 'ended', outcome, at: input.at };
  return { ...out(st), state: st };
}

function stop(input, ctx) {
  // Stopped by a counted customer cancel (R6.2): the order ends by R6.2, never by R4.5.
  const st = { status: 'stopped', outcome: null, at: null };
  return { ...out(st), state: st };
}

function resume(input, ctx) {
  // §3.5: a migrated order that is already processing (or ended).
  const r = input.records?.progress ?? {};
  const st = { status: r.status ?? 'processing', outcome: r.outcome ?? null, at: r.at ?? null };
  return { ...out(st), state: st };
}
// Module statuses, key: the order id. The only writer of orders.setStatus. Owns R7.2 (forward moves only, each
// status at most once, never moved back by a late or repeated request) and the §2 setStatus row (the system does not
// check transitions, so we do). Local keys: 'order.<status>' and 'f.<fulfilmentId>.<status>' (one key per change).
// Always returns `output`.

const ORDER_TERMINAL = ['completed', 'failed', 'cancelled', 'timedOut'];
const FULFILMENT_TERMINAL = ['completed', 'failed', 'cancelled'];

// Allowed moves (R7.2). The order: pending -> customerActionRequired -> processing -> end. The fulfilment:
// pending -> processing -> dispatched -> completed, with cancelled / failed as other ends, and unavailable -> cancelled.
function allowed(target, current, status) {
  if (current === undefined || current === null) return false;
  if (target === 'order') {
    if (ORDER_TERMINAL.includes(current)) return false;
    if (status === 'cancelled') return true;
    if (status === 'customerActionRequired') return current === 'pending';
    if (status === 'processing') return current === 'pending' || current === 'customerActionRequired';
    if (status === 'completed' || status === 'failed') return current === 'processing';
    if (status === 'timedOut') return current === 'customerActionRequired' || current === 'pending';
    return false;
  }
  if (FULFILMENT_TERMINAL.includes(current)) return false;
  if (status === 'cancelled') return true;
  if (current === 'unavailable') return false;
  if (status === 'processing') return current === 'pending';
  if (status === 'dispatched') return current === 'processing';
  if (status === 'completed') return current === 'processing' || current === 'dispatched';
  if (status === 'failed') return current === 'pending' || current === 'processing' || current === 'dispatched';
  return false;
}

function out(st, applied, busy) {
  return {
    output: {
      applied,
      order: st?.order ?? null,
      fulfilments: st ? Object.entries(st.f).map(([fulfilmentId, status]) => ({ fulfilmentId, status })) : [],
      busy,
    },
  };
}

function readJson(files, path) {
  let v = files?.[path];
  if (v === undefined) { v = files; for (const seg of path.split('/')) v = v?.[seg]; }
  if (typeof v === 'string') return JSON.parse(v);
  return v ?? null;
}

// The API may rename a field during the run; api/<system>.schema.json in ctx.files always shows the current names
// (SPEC-E §4.2). An argument the current schema no longer names moves to the single property that replaces it.
function fit(system, op, args, ctx) {
  const schema = readJson(ctx.files, `api/${system}.schema.json`);
  const a = schema?.ops?.[op]?.args;
  if (!a || !a.properties || !args) return args;
  const props = Object.keys(a.properties);
  const out = { ...args };
  for (const k of Object.keys(args).filter(k => !props.includes(k))) {
    const free = props.filter(p => !(p in out));
    const req = free.filter(p => (a.required ?? []).includes(p));
    const pick = req.length === 1 ? req[0] : free.length === 1 ? free[0] : null;
    if (pick) { out[pick] = out[k]; delete out[k]; }
  }
  return out;
}

export function step(input, ctx) {
  switch (input.op) {
    case 'init': return init(input, ctx);
    case 'set': return set(input, ctx);
    case 'get': return out(ctx.state, false, anyInflight(ctx.state));
    case 'resume': return resume(input, ctx);
  }
  throw new Error(`statuses: unknown op ${input.op}`);
}

export function onEvent(event, ctx) {
  // Result of one setStatus: it is no longer in flight. A refused result is recorded but changes nothing else.
  const st = ctx.state ? { ...ctx.state, inflight: { ...ctx.state.inflight } } : null;
  if (st && event.payload && typeof event.payload.key === 'string') delete st.inflight[event.payload.key];
  return { ...out(st, false, anyInflight(st)), state: st };
}

function anyInflight(st) {
  return !!st && Object.keys(st.inflight ?? {}).length > 0;
}

function init(input, ctx) {
  if (ctx.state) return { ...out(ctx.state, false, anyInflight(ctx.state)) };
  const f = {};
  for (const x of input.fulfilments) f[x.fulfilmentId] = x.location === null ? 'unavailable' : 'pending';
  const st = { order: 'pending', f, inflight: {}, last: null };
  return { ...out(st, false, false), state: st };
}

function set(input, ctx) {
  const st = ctx.state;
  if (!st) return { ...out(null, false, false) };          // before init: refused (R4.1)
  const isOrder = input.fulfilmentId === null || input.fulfilmentId === undefined;
  const target = isOrder ? 'order' : 'fulfilment';
  const fid = isOrder ? null : input.fulfilmentId;
  const cur = isOrder ? st.order : st.f[fid];
  const next = { ...st, f: { ...st.f }, inflight: { ...st.inflight } };
  if (!allowed(target, cur, input.status)) return { ...out(st, false, anyInflight(st)) };
  const key = isOrder ? `order.${input.status}` : `f.${fid}.${input.status}`;
  if (isOrder) next.order = input.status; else next.f[fid] = input.status;
  const effect = { key, system: 'orders', op: 'setStatus', args: fit('orders', 'setStatus', { orderId: ctx.key, fulfilmentId: fid, status: input.status }, ctx) };
  if (input.afterStatus && !isOrder) {
    const earlier = `f.${fid}.${input.afterStatus}`;
    if (next.last && next.last.key === earlier && next.last.now === ctx.now) effect.after = earlier;
  }
  next.last = { key, now: ctx.now };
  next.inflight[key] = true;
  return { ...out(next, true, true), state: next, effects: [effect] };
}

function resume(input, ctx) {
  // §3.5: the statuses already on the records of a migrated order (input.records.statuses: { order, fulfilments }).
  const r = input.records?.statuses ?? {};
  const f = {};
  for (const x of r.fulfilments ?? []) f[x.fulfilmentId] = x.status;
  const st = { order: r.order ?? 'pending', f, inflight: {}, last: null };
  return { ...out(st, false, false), state: st };
}
// Module notices, key: the order id. The only sender of notify.send. Owns §4.8 (each required notice exactly once,
// `to` is the customer's email, `about` the order id or, for fulfilment-failed, the fulfilment id).
// Local keys: '<template>.<about>' and 'cancel-refused.<occurrence>'. Always returns `output`.

const TEXT = {
  'action-required': 'Some items of your order are not available. Please amend or cancel the order before the deadline.',
  'order-cancelled': 'Your order has been cancelled.',
  'order-timed-out': 'Your order was not confirmed in time and has been closed.',
  'fulfilment-failed': 'Part of your order could not be fulfilled and has been reversed.',
  'cancel-refused': 'Your order has already been collected and can no longer be cancelled.',
  'unknown-order': 'We could not find an order with that reference.',
};

function readJson(files, path) {
  let v = files?.[path];
  if (v === undefined) { v = files; for (const seg of path.split('/')) v = v?.[seg]; }
  if (typeof v === 'string') return JSON.parse(v);
  return v ?? null;
}

// The API may rename a field during the run; api/<system>.schema.json in ctx.files always shows the current names
// (SPEC-E §4.2). An argument the current schema no longer names moves to the single property that replaces it.
function fit(system, op, args, ctx) {
  const schema = readJson(ctx.files, `api/${system}.schema.json`);
  const a = schema?.ops?.[op]?.args;
  if (!a || !a.properties || !args) return args;
  const props = Object.keys(a.properties);
  const out = { ...args };
  for (const k of Object.keys(args).filter(k => !props.includes(k))) {
    const free = props.filter(p => !(p in out));
    const req = free.filter(p => (a.required ?? []).includes(p));
    const pick = req.length === 1 ? req[0] : free.length === 1 ? free[0] : null;
    if (pick) { out[pick] = out[k]; delete out[k]; }
  }
  return out;
}

export function step(input, ctx) {
  switch (input.op) {
    case 'init': return init(input, ctx);
    case 'send': return send(input, ctx);
    case 'get': return out(ctx.state, false);
    case 'resume': return resume(input, ctx);
  }
  throw new Error(`notices: unknown op ${input.op}`);
}

export function onEvent(event, ctx) {
  const st = ctx.state ? { ...ctx.state, inflight: { ...ctx.state.inflight } } : null;
  if (st && event.payload && typeof event.payload.key === 'string') delete st.inflight[event.payload.key];
  return { ...out(st, false), state: st };
}

function out(st, sent) {
  return { output: { sent, busy: !!st && Object.keys(st.inflight ?? {}).length > 0 } };
}

function rowsOf(x) {
  if (Array.isArray(x)) return x;
  if (x && typeof x === 'object') {
    const arr = Object.values(x).find(v => Array.isArray(v));
    if (arr) return arr;
    return Object.entries(x).map(([k, v]) => ({ customerId: k, ...(typeof v === 'object' ? v : {}) }));
  }
  return [];
}

function emailOf(ctx, customerId) {
  const f = ctx.files ?? {};
  let c = f['master/customers.json'];
  if (typeof c === 'string') c = JSON.parse(c);
  const row = rowsOf(c).find(r => r && r.customerId === customerId);
  if (!row || typeof row.email !== 'string') throw new Error(`no email for customer ${customerId}`);
  return row.email;
}

function init(input, ctx) {
  if (ctx.state) return out(ctx.state, false);
  const st = { customerId: input.customerId, email: emailOf(ctx, input.customerId), sent: {}, inflight: {} };
  return { ...out(st, false), state: st };
}

function send(input, ctx) {
  const st = ctx.state;
  if (!st) throw new Error('notices.send before init');
  const key = input.template === 'cancel-refused' ? `cancel-refused.${input.occurrence}` : `${input.template}.${input.about}`;
  if (st.sent[key]) return { ...out(st, false) };          // exactly once
  const next = { ...st, sent: { ...st.sent, [key]: true }, inflight: { ...st.inflight, [key]: true } };
  const effect = {
    key, system: 'notify', op: 'send',
    args: fit('notify', 'send', { to: st.email, about: input.about, template: input.template, text: input.text ?? TEXT[input.template], ref: null }, ctx),
  };
  return { ...out(next, true), state: next, effects: [effect] };
}

function resume(input, ctx) {
  // §3.5: notices already on the migrated records count as sent.
  const r = input.records?.notices ?? {};
  const st = { customerId: input.customerId ?? r.customerId, email: r.email ?? emailOf(ctx, input.customerId), sent: {}, inflight: {} };
  for (const k of r.sent ?? []) st.sent[k] = true;
  return { ...out(st, false), state: st };
}

